// Step 1: Input Validation and Fault Latching
int fault_latched = 0;

// Check NULL pointers
if (ag_input.current_q_bi == NULL || ag_input.target_q_bi == NULL || ag_input.rate_rad_s == NULL) {
    fault_latched = 1;
}

// Check config limits validity
if (!fault_latched) {
    if (!isfinite(ag_config.angle_limit_rad) || ag_config.angle_limit_rad < 0.0 || ag_config.angle_limit_rad > ADCS_PI) {
        fault_latched = 1;
    }
    if (!isfinite(ag_config.rate_limit_rad_s) || ag_config.rate_limit_rad_s < 0.0) {
        fault_latched = 1;
    }
    if (ag_config.required < 1 || ag_config.required > 20) {
        fault_latched = 1;
    }
}

// Check telemetry finiteness
if (!fault_latched) {
    if (!isfinite(ag_input.current_q_bi->w) || !isfinite(ag_input.current_q_bi->x) || 
        !isfinite(ag_input.current_q_bi->y) || !isfinite(ag_input.current_q_bi->z)) {
        fault_latched = 1;
    }
    if (!isfinite(ag_input.target_q_bi->w) || !isfinite(ag_input.target_q_bi->x) || 
        !isfinite(ag_input.target_q_bi->y) || !isfinite(ag_input.target_q_bi->z)) {
        fault_latched = 1;
    }
    if (!isfinite(ag_input.rate_rad_s->x) || !isfinite(ag_input.rate_rad_s->y) || 
        !isfinite(ag_input.rate_rad_s->z)) {
        fault_latched = 1;
    }
}

if (fault_latched) {
    ag_output.mode = AG_FAULT;
    // Preserve prior count for fault as per table: "invalid telemetry/configuration -> latched FAULT -> preserve prior count"
    ag_output.good = ag_state.good;
    ag_output.angle_rad = 0.0;
    ag_output.rate_norm_rad_s = 0.0;
    ag_output.rate_energy = 0.0;
    return;
}

// Step 2: Normalize Quaternions
adcs_quat_t q_curr_norm, q_tgt_norm;
if (adcs_quat_normalize(ag_input.current_q_bi, &q_curr_norm) != ADCS_OK) {
    // Degenerate quaternion -> Fault
    ag_output.mode = AG_FAULT;
    ag_output.good = ag_state.good;
    ag_output.angle_rad = 0.0;
    ag_output.rate_norm_rad_s = 0.0;
    ag_output.rate_energy = 0.0;
    return;
}
if (adcs_quat_normalize(ag_input.target_q_bi, &q_tgt_norm) != ADCS_OK) {
    ag_output.mode = AG_FAULT;
    ag_output.good = ag_state.good;
    ag_output.angle_rad = 0.0;
    ag_output.rate_norm_rad_s = 0.0;
    ag_output.rate_energy = 0.0;
    return;
}

// Step 3: Compute Relative Rotation and Angle
// q_rel = q_curr_conj * q_tgt
adcs_quat_t q_curr_conj = adcs_quat_conjugate(&q_curr_norm);
adcs_quat_t q_rel = adcs_quat_multiply(&q_curr_conj, &q_tgt_norm);

// Shortest angle: theta = 2 * acos(|w_rel|)
double abs_w_rel = fabs(q_rel.w);
// Clamp to [-1, 1] for safety against floating point errors
if (abs_w_rel > 1.0) abs_w_rel = 1.0;
double angle_rad = 2.0 * acos(abs_w_rel);

// Step 4: Compute Rate Norm and Energy
double rate_norm = adcs_vec3_norm(ag_input.rate_rad_s);
double rate_energy = adcs_vec3_dot(ag_input.rate_rad_s, ag_input.rate_rad_s);

// Step 5: Settling Gate Logic
ag_mode_t next_mode = ag_state.mode;
unint32 next_good = ag_state.good;

if (!ag_input.enable) {
    // Disabled: SLEW, clear evidence
    next_mode = AG_SLEW;
    next_good = 0;
} else {
    // Enabled
    if (angle_rad <= ag_config.angle_limit_rad && rate_norm <= ag_config.rate_limit_rad_s) {
        // Within limits
        next_good++;
        if (next_good >= ag_config.required) {
            next_mode = AG_SETTLED;
        } else {
            // Preserve current mode
            next_mode = ag_state.mode;
        }
    } else {
        // Violation
        next_mode = AG_SLEW;
        next_good = 0;
    }
}

// Step 6: Update State and Output
ag_state.mode = next_mode;
ag_state.good = next_good;

ag_output.mode = next_mode;
ag_output.good = next_good;
ag_output.angle_rad = angle_rad;
ag_output.rate_norm_rad_s = rate_norm;
ag_output.rate_energy = rate_energy;

